87:         return { valid: false, discountAmount: 0, message: "Please enter a promo code." };
88:     }
89: 
90:     if (code === "FLAVOUR10") {
91:         if (subtotal <= 0) {
92:             return { valid: false, discountAmount: 0, message: "Add items to your cart before applying a promo code." };
93:         }
94:         const discount = Math.round(subtotal * 0.10);
95:         return { valid: true, discountAmount: discount, message: "Promo FLAVOUR10 applied (10% off)." };
96:     }
97: 
98:     if (code === "WELCOME100") {
99:         if (subtotal < WELCOME_MIN_SUBTOTAL) {
100:             return {
101:                 valid: false,
102:                 discountAmount: 0,
103:                 message: "WELCOME100 requires a minimum subtotal of Rs. 1,000."
104:             };
105:         }
106:         return { valid: true, discountAmount: 100, message: "Promo WELCOME100 applied (Rs. 100 off)." };
107:     }
108: 
109:     return {
110:         valid: false,
111:         discountAmount: 0,
112:         message: "Invalid promo code. Try FLAVOUR10 or WELCOME100."
113:     };
114: }
