116: // Calculate and update the Order Summary card (Subtotal, Discount, Delivery, Tax, Total)
117: function updateOrderSummary(cart) {
118:     const subtotalElement = document.getElementById("summarySubtotal");
119:     const discountRow = document.getElementById("discountRow");
120:     const appliedPromoLabel = document.getElementById("appliedPromoLabel");
121:     const summaryDiscount = document.getElementById("summaryDiscount");
122:     const deliveryElement = document.getElementById("summaryDelivery");
123:     const taxElement = document.getElementById("summaryTax");
124:     const totalElement = document.getElementById("summaryTotal");
125:     const checkoutBtn = document.getElementById("checkoutBtn");
126:     const promoInput = document.getElementById("promoInput");
127: 
128:     // Guard: if FlavourCart failed to load, show zeros and disable checkout
129:     if (typeof FlavourCart === "undefined") {
130:         if (subtotalElement) subtotalElement.textContent = "Rs. 0";
131:         if (deliveryElement) deliveryElement.textContent = "Rs. 0";
132:         if (taxElement) taxElement.textContent = "Rs. 0";
133:         if (totalElement) totalElement.textContent = "Rs. 0";
134:         if (checkoutBtn) {
135:             checkoutBtn.classList.add("disabled");
136:             checkoutBtn.setAttribute("aria-disabled", "true");
137:         }
138:         return;
139:     }
140: 
141:     // Calculate subtotal using the shared FlavourCart helper
142:     const subtotal = FlavourCart.getTotalPrice(cart);
143:     const isEmpty = cart.length === 0;
144:     const deliveryFee = isEmpty ? 0 : DELIVERY_FEE;
145: 
146:     let discountAmount = 0;
147:     const savedPromo = getSavedPromo();
148: 
149:     if (isEmpty) {
150:         if (savedPromo) {
151:             clearPromo();
152:             setPromoMessage("", "");
153:         }
154:     } else if (savedPromo) {
155:         const result = evaluatePromoCode(savedPromo.code, subtotal);
156:         if (result.valid) {
157:             discountAmount = result.discountAmount;
158:             savePromo(savedPromo.code, discountAmount);
159:             if (!promoInput.value) {
160:                 promoInput.value = savedPromo.code;
161:             }
162:             appliedPromoLabel.textContent = savedPromo.code;
163:             summaryDiscount.textContent = "- " + formatPrice(discountAmount);
164:             discountRow.classList.remove("d-none");
165:         } else {
166:             clearPromo();
167:             setPromoMessage(result.message, "error");
168:         }
169:     }
170: 
171:     if (discountAmount === 0) {
172:         discountRow.classList.add("d-none");
173:     }
174: 
175:     // Tax is 5% of the subtotal after discount
176:     const subtotalAfterDiscount = Math.max(0, subtotal - discountAmount);
177:     const tax = isEmpty ? 0 : Math.round(subtotalAfterDiscount * TAX_RATE);
178:     const total = subtotalAfterDiscount + deliveryFee + tax;
179: 
180:     subtotalElement.textContent = formatPrice(subtotal);
181:     deliveryElement.textContent = formatPrice(deliveryFee);
182:     taxElement.textContent = formatPrice(tax);
183:     totalElement.textContent = formatPrice(total);
184: 
185:     // Disable "Proceed to Checkout" when the cart is empty
186:     if (isEmpty) {
187:         checkoutBtn.classList.add("disabled");
188:         checkoutBtn.setAttribute("aria-disabled", "true");
189:         checkoutBtn.setAttribute("tabindex", "-1");
190:     } else {
191:         checkoutBtn.classList.remove("disabled");
192:         checkoutBtn.removeAttribute("aria-disabled");
193:         checkoutBtn.removeAttribute("tabindex");
194:     }
195: }
