205: // Change an item's quantity (+1 or -1) while enforcing the 1..20 limits
206: function changeQuantity(itemId, delta) {
207:     const cart = FlavourCart.getCart();
208:     const item = cart.find(function (entry) {
209:         return entry.id === String(itemId);
210:     });
211: 
212:     if (!item) {
213:         return;
214:     }
215: 
216:     const nextQty = item.quantity + delta;
217: 
218:     if (nextQty < MIN_QTY) {
219:         showInlineQtyError(itemId, "Minimum quantity is 1.");
220:         return;
221:     }
222: 
223:     if (nextQty > MAX_QTY) {
224:         showInlineQtyError(itemId, "Maximum quantity is 20.");
225:         return;
226:     }
227: 
228:     // Update via shared helper (which saves to flavourLoungeCart and syncs navbar badge)
229:     FlavourCart.updateQuantity(itemId, nextQty);
230:     renderCart();
231: }
