358: // Handle promo code form submission
359: function handlePromoSubmit(event) {
360:     event.preventDefault();
361: 
362:     // Guard against missing FlavourCart
363:     if (typeof FlavourCart === "undefined") {
364:         setPromoMessage("Cart not available. Please reload the page.", "error");
365:         return;
366:     }
367: 
368:     const promoInput = document.getElementById("promoInput");
369:     const rawCode = promoInput.value.trim().toUpperCase();
370:     const cart = FlavourCart.getCart();
371:     const subtotal = FlavourCart.getTotalPrice(cart);
372: 
373:     const result = evaluatePromoCode(rawCode, subtotal);
374: 
375:     if (!result.valid) {
376:         setPromoMessage(result.message, "error");
377:         return;
378:     }
379: 
380:     savePromo(rawCode, result.discountAmount);
381:     setPromoMessage(result.message, "success");
382:     updateOrderSummary(cart);
